{"sub":"r/PinkUnion","theme_id":"T2-55219","batch":"S05-01","agent":"oa2","replicate":1,"position":6,"third_order":["T3-030","T3-193"],"multi":true,"why":{"T3-030":"The exchanges judge the alliance's conduct and worth, dispute allegations against OSU and debate terminating the relationship; they do not simply enforce an agreed border.","T3-193":"The backdrop and servitude objections separately frame cooperation itself as submission."},"confidence":"clear","read":"whole","exemplar_read":null,"families_opened":["G10","G15"],"bag":false,"t_start":null,"t":null,"support":["C0038931","C1520827","C0627520","C0914563","C0751437","C0514318","C0856373","C0448393","C0964446","C1472870","C0957491"],"support_by_theme":{"T3-030":["C0038931","C1520827","C0627520","C0914563","C0751437","C0514318","C0856373","C0448393","C0964446"],"T3-193":["C1472870","C0957491"]},"also_present":{},"multiplacement_log":[{"sub":"r/PinkUnion","theme_id":"T2-55219","key":"r/PinkUnion/T2-55219","batch":"S05-01","agent":"oa2","replicate":1,"position":6,"primary":"T3-030","additional":"T3-193","why_not_one":"Disputing OSU's conduct does not fully carry the separate rejection of background work as an inherently subordinate relationship.","why_this_one":"C0957491 explicitly calls the arrangement servitude, and C1472870 refuses the subordinate backdrop role.","support_primary":["C1520827","C0514318","C0448393","C0964446"],"support_additional":["C1472870","C0957491"],"dispensable":"T3-193; dropping it would lose the argument that cooperation itself constitutes submission."}]}
